                double[] dd = this.data;
                double _t0_inv = 1.0 / (right - left);
                double _t1_inv = 1.0 / (top - bottom);
                dd[0] = _t0_inv + _t0_inv;
                dd[1] = 0.0;
                dd[2] = 0.0;
                dd[3] = 0.0;
                dd[4] = 0.0;
                dd[5] = _t1_inv + _t1_inv;
                dd[6] = 0.0;
                dd[7] = 0.0;
