    private Double4x4 scaleAround_narrow(double s, Double3R pivot, @Mutated Double4x4 dest) {
        double[] pivotData = ((Double3Impl) pivot).data;
        double pivotX = pivotData[0];
        double pivotY = pivotData[1];
        double pivotZ = pivotData[2];
        int p = this.properties;
        if ((p & Joml.BIT_AFFINE) != Joml.BIT_AFFINE) return (org.joml2.internal.FmaSwitch.ON ? scaleAround_general_fma_narrow(s, pivotX, pivotY, pivotZ, dest) : scaleAround_general_mulAdd_narrow(s, pivotX, pivotY, pivotZ, dest));
        if ((p & Joml.BIT_IDENTITY) == Joml.BIT_IDENTITY) {
            double[] dd = ((Double4x4Impl) dest).data;
            double _t0 = 1.0 - s;
            dd[0] = s;
            dd[1] = 0.0;
            dd[2] = 0.0;
            dd[3] = 0.0;
            dd[4] = 0.0;
            dd[5] = s;
            dd[6] = 0.0;
            dd[7] = 0.0;
            dd[8] = 0.0;
            dd[9] = 0.0;
            dd[10] = s;
            dd[11] = 0.0;
            dd[12] = pivotX * _t0;
            dd[13] = pivotY * _t0;
            dd[14] = pivotZ * _t0;
            dd[15] = 1.0;
            ((Double4x4Impl) dest).properties = Joml.BIT_AFFINE;
            return dest;
        }
        if ((p & Joml.BIT_TRANSLATION) == Joml.BIT_TRANSLATION) return (org.joml2.internal.FmaSwitch.ON ? scaleAround_translation_fma_narrow(s, pivotX, pivotY, pivotZ, dest) : scaleAround_translation_mulAdd_narrow(s, pivotX, pivotY, pivotZ, dest));
        return (org.joml2.internal.FmaSwitch.ON ? scaleAround_orthogonal_fma_narrow(s, pivotX, pivotY, pivotZ, dest) : scaleAround_orthogonal_mulAdd_narrow(s, pivotX, pivotY, pivotZ, dest));
    }

